CREATE TABLE metadata_policy_resolutions (generation INTEGER NOT NULL, library_name TEXT NOT NULL, resolved_policy_id TEXT NOT NULL CHECK(resolved_policy_id GLOB 'resolved_policy_[0-9a-f]*' AND length(resolved_policy_id)=80), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 16384), PRIMARY KEY(generation,library_name));
CREATE TABLE metadata_policy_state (singleton INTEGER PRIMARY KEY NOT NULL CHECK(singleton=1), active_policy_id TEXT NOT NULL REFERENCES metadata_policy_drafts(policy_id), generation INTEGER NOT NULL CHECK(generation>=1), activated_at INTEGER NOT NULL CHECK(activated_at>=0), posture TEXT NOT NULL CHECK(posture IN ('review','preview','automatic')));
