CREATE TABLE metadata_policy_transition_items (transition_id TEXT NOT NULL REFERENCES metadata_policy_transitions(transition_id), connection_name TEXT NOT NULL, library_name TEXT NOT NULL, item_id TEXT NOT NULL, report_id TEXT NOT NULL REFERENCES metadata_reports(report_id), work_id TEXT REFERENCES review_preparation_work(work_id), state TEXT NOT NULL CHECK(state IN ('pending','complete','failed')), failure_code TEXT CHECK(failure_code IS NULL OR failure_code IN ('pipeline_unavailable','stale','failed')), updated_at INTEGER NOT NULL CHECK(updated_at>=0), PRIMARY KEY(transition_id,connection_name,library_name,item_id));
CREATE TABLE metadata_policy_transitions (transition_id TEXT PRIMARY KEY NOT NULL CHECK(transition_id GLOB 'policy_transition_[0-9a-f]*' AND length(transition_id)=82), from_policy_id TEXT NOT NULL REFERENCES metadata_policy_drafts(policy_id), to_policy_id TEXT NOT NULL REFERENCES metadata_policy_drafts(policy_id), generation INTEGER NOT NULL UNIQUE CHECK(generation>=1), state TEXT NOT NULL CHECK(state IN ('processing','completed','completed_with_failures')), total INTEGER NOT NULL CHECK(total>=0), acknowledged INTEGER NOT NULL DEFAULT 0 CHECK(acknowledged IN (0,1)), created_at INTEGER NOT NULL CHECK(created_at>=0), updated_at INTEGER NOT NULL CHECK(updated_at>=created_at));
